//! The font atlas (`assets/fonts/atlas.ron` + `atlas.png`, ADR-0012): a grid
//! of fixed-size glyph cells and the map from `char` to cell index.
//!
//! Both files are generated by `cargo shuyi font-atlas` from the bitmap font
//! described in `assets/fonts/README.md`, and committed. The atlas is Shuyi
//! Engine's (`shuyi_assets::font`, ticket 1104); this module names the
//! game's files and the glyphs the game draws.
use crate::prelude::*;

pub use shuyi_assets::font::{AtlasRect, FALLBACK_GLYPH, FontAtlasDef, describe};
pub use shuyi_assets::image::png_size;

use crate::bundle;
use crate::error::ContentError;
use crate::formats;

/// Path of the glyph map inside the asset bundle.
pub const ATLAS_PATH: &str = "fonts/atlas.ron";
/// Path of the atlas image (white glyphs on transparent) inside the bundle.
pub const ATLAS_PNG_PATH: &str = "fonts/atlas.png";
/// Path of the one-bit atlas (ADR-0074) inside the bundle: the same glyphs
/// as [`ATLAS_PNG_PATH`], packed for the Playdate so it never decodes a
/// PNG. Each glyph, in cell index order, is `cell_h` bytes, one per pixel
/// row from the top; a byte's highest bit is the row's left pixel, and a
/// set bit is a pixel of the glyph. So a cell is at most 8 pixels wide.
pub const ATLAS_1BIT_PATH: &str = "fonts/atlas_1bit.bin";

/// Glyphs the game draws and the atlas must therefore contain: printable
/// ASCII, Latin-1, box drawing, blocks and the CP437-style symbols used by
/// maps and UI (ADR-0012).
pub const REQUIRED_GLYPHS: &str = concat!(
    // Printable ASCII.
    " !\"#$%&'()*+,-./0123456789:;<=>?@ABCDEFGHIJKLMNOPQRSTUVWXYZ[\\]^_`",
    "abcdefghijklmnopqrstuvwxyz{|}~",
    // Latin-1 supplement (the U+00AD soft hyphen is invisible, so escaped).
    "¡¢£¤¥¦§¨©ª«¬\u{ad}®¯°±²³´µ¶·¸¹º»¼½¾¿",
    "ÀÁÂÃÄÅÆÇÈÉÊËÌÍÎÏÐÑÒÓÔÕÖ×ØÙÚÛÜÝÞß",
    "àáâãäåæçèéêëìíîïðñòóôõö÷øùúûüýþÿ",
    // Box drawing.
    "─│┌┐└┘├┤┬┴┼═║╔╗╚╝╠╣╦╩╬",
    // Blocks and bars.
    "░▒▓█▀▄▌▐■",
    // Symbols (the ticket also lists · and ¤, which are Latin-1 above).
    "♣♠♥♦≈•ˇ▲▼◄►←↑→↓☺☻♪†",
    // The terrain of the places behind conversations (ticket 0733).
    "╱╲╤╫∩≡◊",
);

/// Loads and validates the embedded glyph map against the embedded image.
pub fn load() -> Result<FontAtlasDef, Vec<ContentError>> {
    formats::load(ATLAS_PATH)
}

/// Parses glyph map `source` (errors attributed to `file`) and validates
/// it against [`REQUIRED_GLYPHS`] and the atlas image `png` (`None` if
/// missing).
pub fn from_source(
    file: &str,
    source: &str,
    png: Option<&[u8]>,
) -> Result<FontAtlasDef, Vec<ContentError>> {
    let png_file = bundle::display_path(ATLAS_PNG_PATH);
    FontAtlasDef::from_source(file, source, &png_file, png, REQUIRED_GLYPHS)
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::image::png_header;

    #[test]
    fn required_glyphs_cover_ascii_and_latin1() {
        let set: Vec<char> = REQUIRED_GLYPHS.chars().collect();
        for c in (' '..='~').chain('\u{a1}'..='\u{ff}') {
            assert!(set.contains(&c), "missing {}", describe(c));
        }
        let mut unique = set.clone();
        unique.sort_unstable();
        unique.dedup();
        assert_eq!(unique.len(), set.len(), "duplicates in REQUIRED_GLYPHS");
        assert!(set.contains(&FALLBACK_GLYPH));
    }

    #[test]
    fn from_source_checks_the_games_glyphs_and_names_its_image() {
        let src = "(cell_w: 8, cell_h: 16, columns: 16, glyphs: {'a': 0})";
        let errs = from_source("a.ron", src, Some(&png_header(128, 16)))
            .err()
            .unwrap_or_default();
        assert_eq!(errs.len(), 1, "{errs:?}");
        assert!(
            errs[0]
                .message
                .starts_with("missing required glyphs: ' ' (U+0020)")
        );
        let errs = from_source("a.ron", src, None).err().unwrap_or_default();
        assert_eq!(
            errs.last().map(ToString::to_string).as_deref(),
            Some("assets/fonts/atlas.png: file not found in asset bundle")
        );
    }

    #[test]
    fn embedded_atlas_loads_with_every_required_glyph() {
        let def = load();
        assert!(def.is_ok(), "{def:?}");
        let def = def.unwrap_or_default();
        assert_eq!((def.cell_w, def.cell_h), (8, 16));
        for c in REQUIRED_GLYPHS.chars() {
            assert!(def.glyph_rect(c).is_some(), "missing {}", describe(c));
        }
    }
}
